func (c *Cpu) DecodeARM(op uint32) {
	cond := op >> 28

	if cond == 0xF {
		switch {
		case IsBlx(op):
			c.Blx(op)
			return
		case IsPld(op):
			panic("unsetup pld instruction")
		}
	}

	if !c.Reg.CPSR.CheckCond(cond) {
		c.Seq = arm7.SEQ
		return
	}

	switch {
	case (op>>24)&0xF == 0xF:
		c.Exception(arm7.VEC_SWI, arm7.MODE_SWI)
	case IsBkpt(op):
		c.Exception(arm7.VEC_PREFETCH, arm7.MODE_ABT)
	case IsCoDataReg(op):
		c.CoDataReg(op)
	case arm7.IsB(op):
		c.B(op)
	case arm7.IsBX(op):
		c.BX(op)
	case arm7.IsSDT(op):
		c.Sdt(op)
	case arm7.IsBlock(op):
		c.Block(op)
	case arm7.IsHalf(op):
		c.Half(op)
	case arm7.IsUndefined(op):
		c.Exception(arm7.VEC_UNDEFINED, arm7.MODE_UND)
	case arm7.IsPSR(op):
		c.Psr(op)
	case arm7.IsSWP(op):
		c.Swp(op)
	case arm7.IsMul(op):
		c.Mul(op)
	case IsCLZ(op):
		c.Clz(op)
	case IsQAlu(op):
		c.Qalu(op)
	case IsExtMul(op):
		c.ExtendedMul(op)
	case arm7.IsALU(op):
		// if alu is moved higher, breaks on overlap since compare inst need Set always
		// probably best to just build a decoded table and jump instead of decode on the fly
		c.Alu(op)
	default:
		panic(fmt.Sprintf("nds: unable to decode arm9 arm pc=%08X op=%08X", c.Reg.R[PC], op))
	}
}

func IsPld(op uint32) bool {
	return arm7.IsOpFormat(
		op,
		0b1111_1101_0111_0000_1111_0000_0000_0000,
		0b1111_0101_0101_0000_1111_0000_0000_0000,
	)
}

